{"command":"cd .clearai-reruns/7cb10f98843e1d11b9d4f83d6fa73f14e755c94920e530802f0b9ccbf1d0ad66 && python3 - <<'EOF'
import json, glob
from pathlib import Path
# compute means / diffs directly from raw files
def rd(p): return json.load(open(p))
a=rd('lab/full-052055.json'); b=rd('lab/verify-052055.json')
print('first',a['value'],a['impurity'],'second',b['value'],b['impurity'])
print('mean yield',(a['value']+b['value'])/2,'mean imp',(a['impurity']+b['impurity'])/2,'diff',b['value']-a['value'])
print('margin',0.115-(a['impurity']+b['impurity'])/2)
init=rd('initial.json')['observations']
fulls=[(o['x'],o['y'],o['value'],o['impurity'],'initial') for o in init]
for p in glob.glob('lab/*.json'):
    try: d=rd(p)
    except Exception: continue
    if all(k in d for k in ('x','y','value','impurity')) and d.get('mode')=='full':
        fulls.append((d['x'],d['y'],d['value'],d['impurity'],p))
from collections import defaultdict
g=defaultdict(list)
for x,y,v,i,s in fulls: g[(x,y)].append((v,i,s))
for k,vs in sorted(g.items()):
    mean=sum(v for v,_,_ in vs)/len(vs); im=sum(i for _,i,_ in vs)/len(vs)
    print(k,'n=',len(vs),'mean=%.4f'%mean,'imp=%.5f'%im,'feasible' if im<=0.115 else 'INFEASIBLE','readings',[round(v,4) for v,_,_ in vs])
EOF","description":"Recompute full-point means and margins"}

